"""Generate the simulator's derivative code from symbolic expressions.

Run `uv run python packages/origamy-sim/codegen/generate.py` after changing one.
CI regenerates the code and fails when it differs from what the repository holds.
"""

import subprocess
from functools import singledispatch
from pathlib import Path

import sympy as sp

GENERATED = Path(__file__).parents[1] / "crates" / "origamy-sim" / "src" / "generated"
HEADER = (
    "// Generated by packages/origamy-sim/codegen/generate.py: "
    "edit the generator, not this file.\n"
)


@singledispatch
def rust(expression: sp.Basic) -> str:
    """Rust code for numbers, symbols, sums, products, powers and atan2.

    SymPy's own Rust printer drops the parentheses of a sum inside a product, so this
    one places every parenthesis itself.
    """
    message = f"no Rust for {expression!r}"
    raise TypeError(message)


@rust.register
def _(expression: sp.Symbol) -> str:
    return expression.name


@rust.register
def _(expression: sp.Integer) -> str:
    return f"{int(expression)}.0"


@rust.register
def _(expression: sp.Rational) -> str:
    return f"{expression.p}.0 / {expression.q}.0"


@rust.register
def _(expression: sp.Float) -> str:
    return repr(float(expression))


@rust.register
def _(expression: sp.Add) -> str:
    terms = " + ".join(rust(term) for term in expression.as_ordered_terms())
    return terms.replace("+ -", "- ")


@rust.register
def _(expression: sp.Mul) -> str:
    coefficient, factors = expression.as_coeff_mul()
    text = "*".join(
        rust(f) if isinstance(f, sp.Symbol | sp.Pow) else operand(f) for f in factors
    )
    if coefficient == 1:
        return text
    if coefficient == -1:
        return f"-{text}"
    return f"{operand(coefficient)}*{text}"


METHODS = {
    -1: "recip()",
    sp.Rational(1, 2): "sqrt()",
    sp.Rational(-1, 2): "sqrt().recip()",
}


@rust.register
def _(expression: sp.Pow) -> str:
    base, exponent = expression.as_base_exp()
    if exponent in METHODS:
        return f"{operand(base)}.{METHODS[exponent]}"
    if isinstance(exponent, sp.Integer):
        return f"{operand(base)}.powi({int(exponent)})"
    return f"{operand(base)}.powf({rust(exponent)})"


@rust.register
def _(expression: sp.atan2) -> str:
    y, x = expression.args
    return f"{operand(y)}.atan2({rust(x)})"


def operand(expression: sp.Basic) -> str:
    """Rust code for an expression, in parentheses unless a symbol or a whole number."""
    code = rust(expression)
    whole = isinstance(expression, sp.Integer) and expression >= 0
    return code if whole or isinstance(expression, sp.Symbol) else f"({code})"


def dihedral() -> tuple[sp.Basic, list[sp.Symbol]]:
    """The signed dihedral angle of two triangles about their shared edge.

    The edge runs along `e` from its first vertex.
    `p` and `q` run from that vertex to the vertices opposite the edge, left and right.
    The angle is positive when the sheet folds toward its front, where normals point.
    """
    e, p, q = (sp.Matrix(sp.symbols(f"{name}0:3", real=True)) for name in "epq")
    left = e.cross(p)
    right = q.cross(e)
    sine = e.dot(right.cross(left))
    cosine = sp.sqrt(e.dot(e)) * left.dot(right)
    return sp.atan2(sine, cosine), [*e, *p, *q]


def vectors(names: str) -> list[sp.Matrix]:
    """One symbolic 3-vector per letter, with components such as `p0`, `p1`, `p2`."""
    return [sp.Matrix(sp.symbols(f"{name}0:3", real=True)) for name in names]


def distances() -> dict[str, tuple[str, sp.Basic, list[sp.Symbol]]]:
    """The squared distances between the closest features of two primitives.

    Each holds where its features are closest: the point-to-line distance where the
    point lies beside the segment, the point-to-plane distance where it lies over the
    triangle, and the line-to-line distance where both segments' closest points lie
    inside them.
    """
    p, q = vectors("pq")
    point_point = (p - q).dot(p - q)
    p, a, b = vectors("pab")
    side = (b - a).cross(p - a)
    point_line = side.dot(side) / (b - a).dot(b - a)
    p, a, b, c = vectors("pabc")
    normal = (b - a).cross(c - a)
    point_plane = (p - a).dot(normal) ** 2 / normal.dot(normal)
    a, b, c, d = vectors("abcd")
    normal = (b - a).cross(d - c)
    line_line = (c - a).dot(normal) ** 2 / normal.dot(normal)
    flat = lambda *vs: [s for v in vs for s in v]  # noqa: E731
    return {
        "point_point": ("between the points `p` and `q`", point_point, flat(*vectors("pq"))),
        "point_line": (
            "from the point `p` to the line through `a` and `b`",
            point_line,
            flat(*vectors("pab")),
        ),
        "point_plane": (
            "from the point `p` to the plane through `a`, `b` and `c`",
            point_plane,
            flat(*vectors("pabc")),
        ),
        "line_line": (
            "between the line through `a` and `b` and the line through `c` and `d`",
            line_line,
            flat(*vectors("abcd")),
        ),
    }


def derivatives(
    name: str, doc: str, function: sp.Basic, variables: list[sp.Symbol]
) -> str:
    """A Rust function of a value with its gradient and Hessian in `variables`."""
    n = len(variables)
    gradient = [sp.diff(function, v) for v in variables]
    lower = [(i, j) for i in range(n) for j in range(i + 1)]
    hessian = [sp.diff(gradient[i], variables[j]) for i, j in lower]
    temporaries, reduced = sp.cse(
        [function, *gradient, *hessian],
        symbols=sp.numbered_symbols("t", real=True),
        optimizations="basic",
    )
    value, rest = reduced[0], reduced[1:]
    names = list(dict.fromkeys(str(v)[0] for v in variables))
    arguments = ", ".join(f"{a}: [f64; 3]" for a in names)
    returns = f"(f64, [f64; {n}], [[f64; {n}]; {n}])"
    lines = [
        *(f"/// {line}" if line else "///" for line in doc.splitlines()),
        "#[must_use]",
        f"pub fn {name}({arguments}) -> {returns} {{",
        *(f"    let [{a}0, {a}1, {a}2] = {a};" for a in names),
        *(f"    let {t} = {rust(expression)};" for t, expression in temporaries),
        f"    let gradient = [{', '.join(rust(g) for g in rest[:n])}];",
        f"    let mut hessian = [[0.0; {n}]; {n}];",
    ]
    for (i, j), entry in zip(lower, rest[n:], strict=True):
        lines.append(f"    hessian[{i}][{j}] = {rust(entry)};")
        if i != j:
            lines.append(f"    hessian[{j}][{i}] = hessian[{i}][{j}];")
    lines += [f"    ({rust(value)}, gradient, hessian)", "}"]
    return "\n".join(lines) + "\n"


def main() -> None:
    """Write every generated module, formatted as rustfmt formats the rest."""
    angle, variables = dihedral()
    doc = (
        "The signed dihedral angle about the edge `e`, from the triangle toward `p`\n"
        "on its left to the triangle toward `q` on its right, with its gradient and\n"
        "Hessian in `e`, `p` and `q`.\n"
        "\n"
        "The angle is positive when the sheet folds toward its front.\n"
        "The angle lies in (-π, π]."
    )
    modules = {"dihedral": derivatives("dihedral_angle", doc, angle, variables)}
    modules["distance"] = "\n".join(
        derivatives(
            f"{name}_distance",
            f"The squared distance {between}, with its gradient and Hessian.",
            value,
            symbols,
        )
        for name, (between, value, symbols) in distances().items()
    )
    GENERATED.mkdir(exist_ok=True)
    for name, code in modules.items():
        (GENERATED / f"{name}.rs").write_text(HEADER + "\n" + code)
    index = [
        HEADER.replace("// ", "//! ", 1).rstrip("\n"),
        "//!",
        "//! Each function returns exact derivatives of a symbolic expression.",
        "",
        '#![allow(clippy::pedantic, reason = "the code is generated, not written")]',
        "",
        *(f"mod {name};" for name in modules),
        "",
        *(f"pub use {name}::*;" for name in modules),
    ]
    (GENERATED / "mod.rs").write_text("\n".join(index) + "\n")
    files = [str(GENERATED / f"{name}.rs") for name in ["mod", *modules]]
    subprocess.run(["rustfmt", "--edition", "2024", *files], check=True)


if __name__ == "__main__":
    main()
